import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import * as THREE from '../vendor/three.module.min.js';
import {createFacadePackage,verifyFacadePackage,verifySource,planSignature,fromMizanDraw} from '../src/model.mjs';
import {createFacadeAgentActions} from '../src/agent.mjs';
import {cutStoneLayer} from '../src/stone.mjs';import {layerMask,multiArea,intersection,rect,openRing} from '../src/polygons.mjs';
import {hash,copy} from '../src/core.mjs';import {buildFacadeScene} from '../src/scene.mjs';import {fitCamera} from '../src/viewer.mjs';
import {validateAssetManifest,checkedAssetUrl} from '../src/assets.mjs';
import {sha256Fallback} from '../src/sha256.mjs';import {createHash} from 'node:crypto';
const json=p=>JSON.parse(fs.readFileSync(new URL(p,import.meta.url)));
const built=json('../examples/source-built.json'),transforms=json('../examples/source-transforms.json'),doc=json('../examples/source-C1.json');
const options={transforms,frontSide:'s',maxProjectionM:{s:.7,n:0,e:0,w:0},roofSurfaces:json('../examples/source-roofs.json')};
const layer={id:'wall-1',C:0,o0:0,o1:.045,outer:rect(0,0,3,3),holes:[rect(1,0,2,2)]};
let A,B,C;
test('HTTP-preview SHA-256 matches native reference on padding boundaries and Arabic',()=>{for(const input of ['', 'abc', 'واجهة حجر أبيض',...Array.from({length:140},(_,i)=>'x'.repeat(i)), 'z'.repeat(100000)]){const bytes=new TextEncoder().encode(input);assert.equal(sha256Fallback(bytes),createHash('sha256').update(bytes).digest('hex'));}});
test.before(async()=>{[A,B,C]=await Promise.all(['A','B','C'].map(style=>createFacadePackage(built,{...options,style})));});
test('stone covers known area with a ground-touching door excluded',()=>{const c=cutStoneLayer(layer);assert.ok(Math.abs(c.audit.maskAreaM2-7)<1e-9);assert.ok(c.audit.outsideAreaM2<1e-8);assert.ok(Math.abs(c.audit.maskAreaM2-c.audit.stoneAreaM2-c.audit.jointAreaM2)<1e-7);for(const t of c.tiles)assert.ok(multiArea(intersection(t.polygons,[[rect(1,0,2,2)]]))<1e-8);});
test('concave walls retain partial perimeter tiles',()=>{const c=cutStoneLayer({...layer,outer:[[0,0],[3,0],[3,1],[1,1],[1,3],[0,3]],holes:[]});assert.ok(Math.abs(c.audit.maskAreaM2-5)<1e-8);assert.ok(c.tiles.some(t=>t.areaM2<.05));});
test('arch tangent duplicates normalize without changing area',()=>{assert.equal(openRing([[0,0],[1,0],[1,0],[1,1],[0,1],[0,0]]).length,4);assert.throws(()=>openRing([[0,0],[1,1],[0,1],[1,0]]),/SELF_INTERSECTION/);});
test('curved polygon opening remains clear',()=>{const hole=[[.7,.6],[2.1,.6],[2.1,1.6]];for(let k=0;k<=24;k++){let a=k*Math.PI/24;hole.push([1.4+.7*Math.cos(a),1.6+.7*Math.sin(a)]);}const c=cutStoneLayer({...layer,holes:[hole]});for(const t of c.tiles)assert.ok(multiArea(intersection(t.polygons,[[hole]]))<1e-7);});
test('unsafe scale and excessive tile requests are rejected',()=>{assert.throws(()=>cutStoneLayer(layer,{widthM:.02,heightM:.02,jointM:.001,maxTiles:20}),/RESOURCE_LIMIT/);assert.throws(()=>cutStoneLayer(layer,{jointM:1}),/INVALID_NUMBER/);assert.throws(()=>cutStoneLayer(layer,{recessM:.1}),/STONE_ENVELOPE/);});
test('seed and output are deterministic',async()=>{assert.equal(await hash(cutStoneLayer(layer)),await hash(cutStoneLayer(layer)));assert.notEqual(await hash(cutStoneLayer(layer,{seed:10})),await hash(cutStoneLayer(layer,{seed:11})));});
test('all three proposals preserve every native plan/frame geometry',async()=>{const source=await hash(planSignature(built));for(const p of [A,B,C])assert.equal(await hash(planSignature(p.built)),source);});
test('alternatives differ by geometric roles, not only colors',()=>{const roles=p=>new Set(p.built.s.layers.filter(l=>!l.plan&&l.role!=='frame').map(l=>l.role));assert.ok(roles(A).has('entry-head'));assert.ok(roles(B).has('canopy'));assert.ok(roles(C).has('vertical-fin'));assert.ok(roles(C).has('stepped-fascia'));assert.ok(!roles(B).has('vertical-fin'));});
test('proposal polygons never occlude native openings',()=>{for(const p of [A,B,C])for(const L of p.built.s.layers.filter(l=>l.role!=='frame'&&!l.plan)){const wall=p.built.s.layers.find(w=>w.role==='wall'&&w.piece===L.piece);for(const h of wall.holes)assert.ok(multiArea(intersection(layerMask(L),[[h]]))<1e-7);}});
test('all projection depths stay within explicit budgets',()=>{for(const p of [A,B,C])for(const [s,b]of Object.entries(p.built))for(const l of b.layers.filter(l=>!l.plan&&l.role!=='frame'))assert.ok(l.o1-l.o0<=options.maxProjectionM[s]+1e-9);});
test('mutated source or packet is detected',async()=>{assert.ok(await verifyFacadePackage(A));const changed=copy(A);changed.style.id='B';assert.equal(await verifyFacadePackage(changed),false);const other=copy(built);other.s.layers[0].C+=.1;assert.equal(await verifySource(A,other),false);});
test('non-rigid transforms and implicit projection budgets fail',async()=>{const t=copy(transforms);t.s[0][0]=2;await assert.rejects(createFacadePackage(built,{...options,transforms:t}),/NOT_RIGID/);await assert.rejects(createFacadePackage(built,{transforms,frontSide:'s'}),/EXPLICIT_PROJECTION/);});
test('source built object is unchanged after generation',async()=>{const before=await hash(built);await createFacadePackage(built,{...options,style:'B'});assert.equal(await hash(built),before);});
test('mesh envelopes match packet and remain finite',async()=>{const material=new THREE.MeshStandardMaterial();const model=await buildFacadeScene(THREE,A,{get:()=>material});assert.ok(model.stats.triangles>1000);assert.ok(model.stats.stoneTiles>100);assert.ok(model.bounds.max.y<=5.6);for(const m of model.meshes)for(const v of m.geometry.attributes.position.array)assert.ok(Number.isFinite(v));model.dispose();material.dispose();});
test('all model corners fit landscape and portrait cameras',async()=>{const material=new THREE.MeshStandardMaterial(),model=await buildFacadeScene(THREE,B,{get:()=>material});for(const aspect of [390/600,1366/700,1])for(const side of ['n','s','e','w']){const c=new THREE.PerspectiveCamera(38,aspect,.1,1000);fitCamera(THREE,c,model.bounds,{side,aspect});for(const x of [model.bounds.min.x,model.bounds.max.x])for(const y of [model.bounds.min.y,model.bounds.max.y])for(const z of [model.bounds.min.z,model.bounds.max.z]){const p=new THREE.Vector3(x,y,z).project(c);assert.ok(Math.abs(p.x)<=1&&Math.abs(p.y)<=1&&Math.abs(p.z)<=1);}}model.dispose();material.dispose();});
test('assets require provenance; remote URLs are denied by default',async()=>{assert.throws(()=>validateAssetManifest({id:'fake',rightsStatus:'LICENSE_REVIEWED',name:'stone',source:{},license:{}}),/LICENSE_DETAILS/);await assert.rejects(checkedAssetUrl({url:'https://outside.invalid/map.jpg'},{baseUrl:'https://mizan.invalid/'}),/URL_NOT_ALLOWED/);});
const hooks=()=>({buildAllSides:()=>copy(built),sideTransform:s=>transforms[s],validateDoc:()=>[]});
test('adapter rejects invalid native doc and mutation by native hook',async()=>{await assert.rejects(fromMizanDraw({...doc,schema:'other'},{...hooks(),...options}),/INVALID_NATIVE_DOC/);await assert.rejects(fromMizanDraw(doc,{...hooks(),...options,buildAllSides:d=>{d.north=2;return copy(built);}}),/MUTATED_INPUT/);});
test('agent generates, edits only facade fields, and rejects stale architecture',async()=>{let current=copy(doc);const agent=createFacadeAgentActions({...hooks(),getDocument:()=>current,getOptions:()=>options});const documentHash=await agent.documentHash();const r=await agent.call('facade.generate',{expectedDocumentHash:documentHash,style:'B'});assert.ok((await agent.call('facade.validate',{resultId:r.resultId})).fresh);await assert.rejects(agent.call('facade.edit',{resultId:r.resultId,expectedDocumentHash:documentHash,patch:{walls:[]}}),/EDIT_SCOPE/);const edited=await agent.call('facade.edit',{resultId:r.resultId,expectedDocumentHash:documentHash,patch:{style:'C',stone:{toneVariation:.04}}});assert.equal(edited.result.style.id,'C');current.walls[0].a.x+=.01;assert.equal((await agent.call('facade.validate',{resultId:r.resultId})).fresh,false);await assert.rejects(agent.call('facade.get',{resultId:r.resultId}),/STALE_FACADE/);});
test('agent rejects changed rules and unrecognized tools',async()=>{let rules=copy(options);const agent=createFacadeAgentActions({...hooks(),getDocument:()=>doc,getOptions:()=>rules});const r=await agent.call('facade.generate',{expectedDocumentHash:await agent.documentHash(),style:'B'});rules.maxProjectionM.s=.3;assert.equal((await agent.call('facade.validate',{resultId:r.resultId})).fresh,false);await assert.rejects(agent.call('delete.document',{}),/ACTION_NOT_ALLOWED/);});
